{const n=innerWidth<680?10:18,rnd=(a,b)=>a+Math.random()*(b-a);$('.petals').innerHTML=Array.from({length:n},()=>`<i class="petal" style="--x:${rnd(0,100)}vw;--s:${rnd(8,16)}px;--d:${rnd(12,22)}s;--delay:${rnd(-22,0)}s;--sway:${rnd(-14,14)}vw"></i>`).join('');}
document.querySelectorAll('[data-icon]').forEach(el=>el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon)));
const start='2026-10-15', DAY=86400000, key='xiaonian-cottage-v1';
// 两人所在城市：填上 city、lat、lon 后，首页会显示双方实时天气和距离（天气来自 Open-Meteo，免费、无需注册）
const people=[{name:'小年',avatar:'assets/photo-1.png',alt:'小年的白色小狗头像',city:'湖南 · 长沙',lat:28.23,lon:112.94},{name:'小年对象',avatar:'assets/photo-2.png',alt:'小年对象的棕色小狗头像',city:'上海',lat:31.23,lon:121.47}];
const photos=[{src:'assets/photo-3.png',title:'镜头里，是我们呀',note:'两个人的回忆 · 01'},{src:'assets/photo-4.png',title:'和你靠近一点点',note:'两个人的回忆 · 02'},{src:'assets/photo-5.png',title:'把可爱装进相机里',note:'两个人的回忆 · 03'},{src:'assets/photo-6.png',title:'一起躺在好天气里',note:'两个人的回忆 · 04'}];
const albums=[{id:'us',title:'镜头里的我们',note:'两个人的合照',photos:[0,1]},{id:'cute',title:'像我们的小家伙',note:'可爱的小动物们',photos:[2,3]}];
const automaticDates=[{title:'我们的第一个月',date:'2026-11-15',sub:'每个月的 15 日，都是一个小纪念。'},{title:'在一起的第 100 天',date:'2027-01-22',sub:'2026 年 10 月 15 日计为第 1 天。'},{title:'我们的第一个周年',date:'2027-10-15',sub:'想和你走过四季，再走过好多四季。'}];
let data={diary:[],wishes:[],dates:[],places:[]},filter='all',editing=null,pendingDelete=null,weatherCache=null,loaded=false;
// ===== 云端存储：内容放在 GitHub 仓库的 data.json，图片放在 uploads/ =====
// 游客从网站读取 data.json，只能浏览；管理员用密码解开 admin.json 里加密保存的 GitHub 令牌后才能写入
const REPO={owner:'QuanShengLi0508',repo:'love-house',branch:'main'},API=`https://api.github.com/repos/${REPO.owner}/${REPO.repo}`,TOKEN_KEY='xiaonian-admin-token',freshImages={};
let token=null;try{token=sessionStorage.getItem(TOKEN_KEY)||localStorage.getItem(TOKEN_KEY);}catch{}
const isAdmin=()=>!!token;
const utf8=s=>new TextEncoder().encode(s),fromUtf8=b=>new TextDecoder().decode(b);
function b64encode(bytes){let s='';for(let i=0;i<bytes.length;i+=0x8000)s+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(s);}
function b64decode(str){const s=atob(str.replace(/\s/g,''));return Uint8Array.from(s,c=>c.charCodeAt(0));}
function gh(path,opt={},tk=token){return fetch(`${API}${path}`,{cache:'no-store',...opt,headers:{Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28',Authorization:`Bearer ${tk}`,...(opt.body?{'Content-Type':'application/json'}:{})}});}
async function apiError(r){if(r.status===401){logout(false);return new Error('登录已失效（令牌过期或被撤销），请重新登录或重置管理员。');}if(r.status===403)return new Error('没有写入权限，或操作太频繁，请稍后再试。');if(r.status===404)return new Error('找不到仓库，请检查令牌是否授权了 love-house 仓库。');return new Error(`保存失败（${r.status}），请稍后再试。`);}
async function readFile(path){const r=await gh(`/contents/${path}?ref=${REPO.branch}`);if(r.status===404)return null;if(!r.ok)throw await apiError(r);const j=await r.json();return {sha:j.sha,text:fromUtf8(b64decode(j.content))};}
async function writeFile(path,base64,message,sha){const r=await gh(`/contents/${path}`,{method:'PUT',body:JSON.stringify({message,content:base64,branch:REPO.branch,...(sha?{sha}:{})})});if(!r.ok)throw Object.assign(await apiError(r),{status:r.status});return r.json();}
async function removeFile(path,message){try{const r=await gh(`/contents/${path}?ref=${REPO.branch}`);if(!r.ok)return;const {sha}=await r.json();await gh(`/contents/${path}`,{method:'DELETE',body:JSON.stringify({message,sha,branch:REPO.branch})});}catch{}}
function cleanData(d){return d&&['diary','wishes','dates'].every(k=>Array.isArray(d[k]))?{diary:d.diary,wishes:d.wishes,dates:d.dates,places:Array.isArray(d.places)?d.places:[]}:null;}
async function loadData(){try{let d=null;if(isAdmin()){const f=await readFile('data.json');d=f&&JSON.parse(f.text);}else{const r=await fetch(`data.json?t=${Date.now()}`,{cache:'no-store'});if(r.ok)d=await r.json();}data=cleanData(d)||{diary:[],wishes:[],dates:[],places:[]};}catch(e){notify(e.message&&isAdmin()?e.message:'内容加载失败，请检查网络后刷新。');}loaded=true;render();}
// 读最新的 data.json → 修改 → 写回；如果两人同时保存发生冲突，重试一次
async function commitData(mutate,message){if(!isAdmin())throw new Error('只有管理员可以修改内容。');for(let attempt=0;;attempt++){const f=await readFile('data.json'),cur=cleanData(f&&JSON.parse(f.text))||{diary:[],wishes:[],dates:[],places:[]},next=mutate(structuredClone(cur));try{await writeFile('data.json',b64encode(utf8(JSON.stringify({version:2,...next},null,2))),message,f?.sha);data=next;return;}catch(e){if(attempt||![409,422].includes(e.status))throw e;}}}
async function uploadImage(dataUrl){const path=`uploads/${crypto.randomUUID()}.jpg`;await writeFile(path,dataUrl.split(',')[1],'上传图片');freshImages[path]=dataUrl;return path;}
// 管理员密码 → PBKDF2 派生密钥 → AES-GCM 解密令牌
async function deriveKey(pw,salt,iterations){const base=await crypto.subtle.importKey('raw',utf8(pw),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',hash:'SHA-256',salt,iterations},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
async function checkToken(tk){const r=await fetch(API,{cache:'no-store',headers:{Accept:'application/vnd.github+json',Authorization:`Bearer ${tk}`}});if(r.status===401)throw new Error('令牌无效或已过期。');if(!r.ok)throw new Error('令牌无法访问 love-house 仓库，请检查授权的仓库。');const j=await r.json();if(!j.permissions?.push)throw new Error('令牌没有写入权限，请把 Contents 设为 Read and write。');}
function keepToken(tk,remember){token=tk;try{(remember?localStorage:sessionStorage).setItem(TOKEN_KEY,tk);}catch{}}
function logout(rerender=true){token=null;try{localStorage.removeItem(TOKEN_KEY);sessionStorage.removeItem(TOKEN_KEY);}catch{}if(rerender)loadData();}
async function setupAdmin(tk,pw){await checkToken(tk);const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),iterations=310000,key=await deriveKey(pw,salt,iterations),ct=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,utf8(tk))),cfg={v:1,iterations,salt:b64encode(salt),iv:b64encode(iv),data:b64encode(ct)};keepToken(tk,true);const old=await readFile('admin.json');await writeFile('admin.json',b64encode(utf8(JSON.stringify(cfg,null,2))),'设置管理员密码',old?.sha);if(!await readFile('data.json'))await writeFile('data.json',b64encode(utf8(JSON.stringify({version:2,diary:[],wishes:[],dates:[]},null,2))),'初始化内容');}
async function login(pw,remember){const r=await fetch(`admin.json?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error('还没有设置管理员，请先在下方完成首次设置。');const cfg=await r.json();let tk;try{const key=await deriveKey(pw,b64decode(cfg.salt),cfg.iterations);tk=fromUtf8(await crypto.subtle.decrypt({name:'AES-GCM',iv:b64decode(cfg.iv)},key,b64decode(cfg.data)));}catch{throw new Error('密码不对，再想想 ♡');}await checkToken(tk);keepToken(tk,remember);}
function today(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function epoch(s){return Date.parse(s+'T00:00:00+08:00');}
function distance(s){return Math.round((epoch(s)-epoch(today()))/DAY);}
function loveDay(s=today()){return Math.max(0,Math.floor((epoch(s)-epoch(start))/DAY)+1);}
function dayTag(s){return s<start?'在一起之前':`DAY ${loveDay(s)}`;}
function escapeHTML(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function hasImage(e){return /^uploads\/[\w-]+\.jpg$/.test(e.image||'')||/^data:image\/(png|jpeg|webp);base64,/.test(e.image||'');}
// 刚上传的图片要等网站重新部署（约 1 分钟）才能访问，这期间先用本地数据显示
function imgSrc(e){return freshImages[e.image]||e.image;}
function notify(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function page(){const p=location.hash.slice(1);return ['home','diary','dates','wishes','album','admin'].includes(p)?p:'home';}
const dog=`<svg class="dog" viewBox="0 0 110 95" fill="none" aria-hidden="true"><path d="M26 45C6 60 4 28 20 21c7-4 13 3 17 9M78 31c14-20 34-1 25 17-6 11-14 8-19 1" fill="#e8be91" stroke="#6d5746" stroke-width="2.5"/><path d="M24 44c0-30 59-32 61 0l-2 19c-4 23-55 24-59 0Z" fill="#fffdf5" stroke="#6d5746" stroke-width="2.5"/><circle cx="40" cy="49" r="3" fill="#6d5746"/><circle cx="68" cy="49" r="3" fill="#6d5746"/><path d="m50 56 4 3 4-3m-4 3c-8 10-12 1-12 1m12-1c7 10 12 1 12 1" stroke="#6d5746" stroke-width="2.5" stroke-linecap="round"/><ellipse cx="33" cy="59" rx="7" ry="4" fill="#f1bdc6"/><ellipse cx="76" cy="59" rx="7" ry="4" fill="#f1bdc6"/><path d="M48 80c-8-15-20-2 7 12C80 77 68 65 55 80" fill="#f1bdc6" stroke="#6d5746" stroke-width="2"/></svg>`;
