const crown=[[118,196,70],[196,132,86],[288,184,76],[156,256,60],[252,252,66],[78,252,46],[334,250,48],[204,206,72]];
const tree=`<svg class="tree" viewBox="0 0 400 470" aria-hidden="true"><ellipse cx="204" cy="456" rx="150" ry="12" fill="#e9d6b4" opacity=".6"/><path d="M184 460c4-50-4-100 4-140-16-20-46-34-66-48l6-8c24 12 46 24 64 38 2-20 0-40 6-60h10c0 22 0 44 4 60 20-16 42-28 68-38l6 8c-24 12-48 28-66 48 6 42 0 92 4 140z" fill="#ddb68c" stroke="#8a7158" stroke-width="3" stroke-linejoin="round"/><path d="M196 452c2-30-2-70 2-104M210 440c0-24 2-50-2-70" stroke="#b8936e" stroke-width="2" stroke-linecap="round" fill="none"/><g stroke="#8a7158" stroke-width="7">${crown.map(([x,y,r])=>`<circle cx="${x}" cy="${y}" r="${r}"/>`).join('')}</g><g fill="#c7d7a2">${crown.map(([x,y,r])=>`<circle cx="${x}" cy="${y}" r="${r}"/>`).join('')}</g><g fill="#b2c689"><circle cx="262" cy="262" r="40"/><circle cx="168" cy="268" r="34"/><circle cx="318" cy="238" r="28"/><circle cx="92" cy="258" r="26"/></g><g fill="#f4e3a1" opacity=".85"><ellipse cx="170" cy="96" rx="34" ry="20"/><ellipse cx="96" cy="170" rx="22" ry="14"/><ellipse cx="262" cy="140" rx="26" ry="15"/></g><g fill="#fff8dc"><circle cx="150" cy="150" r="4"/><circle cx="232" cy="98" r="3"/><circle cx="300" cy="200" r="3.5"/><circle cx="120" cy="226" r="3"/><circle cx="208" cy="180" r="2.5"/></g></svg>`;
const leaf=c=>`<svg class="leaf ${c}" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20C4 9 11 4 20 4c0 9-5 16-16 16zM4 20 13 11" fill="#c7d7a2" stroke="#8a7158" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const bigHeart=`<svg viewBox="0 0 48 44" aria-hidden="true"><defs><linearGradient id="hg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#ff9fb4"/><stop offset="1" stop-color="#f0607e"/></linearGradient></defs><path d="M24 41S5 29.6 1.8 18.3A11.4 11.4 0 0 1 24 10.6a11.4 11.4 0 0 1 22.2 7.7C43 29.6 24 41 24 41z" fill="url(#hg)"/><path d="M10 14.5c1.4-2.6 4-4 6.8-3.8" fill="none" stroke="#fff" stroke-width="2.6" stroke-linecap="round" opacity=".85"/></svg>`;
function heading(en,title,sub,action=''){return `<div class="page-heading"><div class="eyebrow">${en}</div><div class="section-head"><div><h2>${title}</h2><p>${sub}</p></div>${action}</div></div>`;}
function addButton(type,label){return isAdmin()?`<button class="button yellow" data-add="${type}">${icon('plus')}${label}</button>`:'';}
function adminActions(e,type){const id=escapeHTML(e.id);return isAdmin()?`<div class="entry-actions">${type==='wishes'?`<button data-toggle="${id}">${e.done?icon('lock')+'重新上锁':icon('unlock')+'解锁这个心愿'}</button>`:''}<button data-edit="${id}" data-type="${type}">${icon('edit')}编辑</button><button data-delete="${id}" data-type="${type}">${icon('trash')}删除</button></div>`:'';}
function photoCard(p,i){return `<button class="polaroid" data-photo="${i}" aria-label="查看${p.title}"><img src="${p.src}" alt="${p.title}" loading="lazy"><p>${p.title}</p><small>${p.note}</small></button>`;}
function placeTag(p){return p?`<span class="place">${icon('pin')}${escapeHTML(p)}</span>`:'';}
function milestone(title,date,sub){const n=distance(date),d=date.split('-');return `<article class="milestone${n<0?' is-past':n===0?' is-today':''}"><div class="calendar"><span>${Number(d[1])} 月</span><strong>${Number(d[2])}</strong></div><div><h3>${escapeHTML(title)}</h3><p class="muted">${escapeHTML(sub)}</p></div><div class="countdown"><b>${Math.abs(n)}</b> 天<span>${n>0?'距离这一天':n<0?'这一天已过去':'就是今天 ♡'}</span></div></article>`;}
function nextMilestone(){const all=[...automaticDates,...data.dates.map(e=>({title:e.title,date:e.date,sub:e.body||'属于我们的小纪念'}))].filter(e=>distance(e.date)>=0).sort((a,b)=>a.date.localeCompare(b.date));return all[0]||automaticDates[automaticDates.length-1];}
function footprintList(){return [...data.places.map(e=>({...e,kind:'place',place:e.title})),...data.diary.map(e=>({...e,kind:'diary'})),...data.wishes.filter(e=>e.done).map(e=>({...e,kind:'wish',date:e.doneDate||e.date}))].filter(e=>e.place).sort((a,b)=>b.date.localeCompare(a.date));}
// 在一起的时长：开始那天的北京时间 0 点起算，开始当天计为第 1 天
function together(){const ms=Math.max(0,Date.now()-epoch(start)),r=ms%DAY,pad=n=>String(n).padStart(2,'0');return {day:loveDay(),h:pad(Math.floor(r/3600000)),m:pad(Math.floor(r/60000)%60),s:pad(Math.floor(r/1000)%60)};}
function home(){const t=together(),w=data.wishes,done=w.filter(e=>e.done).length,pct=w.length?Math.round(done/w.length*100):0,next=nextMilestone(),latest=[...data.diary].sort((a,b)=>b.date.localeCompare(a.date))[0],places=new Set(footprintList().map(e=>e.place)).size,photoCount=photos.length+data.diary.filter(hasImage).length;
return `<section class="hero"><div class="hero-scene" aria-hidden="true"><div class="sun"></div>${tree}${leaf('l1')}${leaf('l2')}${leaf('l3')}</div><div class="couple"><span class="big-heart">${bigHeart}</span></div><h1>喜欢你，是每天的小事</h1><p class="hero-sub">TOGETHER SINCE 2026.10.15</p><div class="love-counter"><div class="avatar-wrap"><img class="avatar" src="${people[0].avatar}" alt="${people[0].alt}"><span class="name-pill">${people[0].name}</span></div><div class="counter"><small>我们已经在一起</small><div><strong id="love-day">${t.day}</strong><span class="unit">天</span></div><div class="clock">${[['h','时'],['m','分'],['s','秒']].map(([k,u])=>`<span><b id="clock-${k}">${t[k]}</b><i>${u}</i></span>`).join('')}</div></div><div class="avatar-wrap"><img class="avatar" src="${people[1].avatar}" alt="${people[1].alt}"><span class="name-pill">${people[1].name}</span></div></div><div class="weather" id="weather" hidden></div></section>
<div class="section-head"><h2>我们的小世界</h2><button class="soft-button" data-random>${icon('shuffle')}随机翻一段回忆</button></div><div class="world-grid"><a class="world-tile wish-tile" href="#wishes"><span class="feature-icon">${icon('star')}</span><span class="arrow">${icon('arrowUR')}</span><b>${done}<small> / ${w.length}</small></b><span class="tile-label">心愿清单</span><div class="progress"><i style="width:${pct}%"></i></div><em>${w.length?`${pct}% 已解锁`:'写下第一个心愿吧'}</em></a>${[['diary','book',data.diary.length,'日常点滴','篇'],['dates','calendar',automaticDates.length+1+data.dates.length,'纪念日','个'],['album','image',photoCount,'相册','张'],['footprints','pin',places,'足迹','处']].map(([p,i,n,t,u])=>`<a class="world-tile" href="#${p}"><span class="feature-icon">${icon(i)}</span><span class="arrow">${icon('arrowUR')}</span><b>${n}<small> ${u}</small></b><span class="tile-label">${t}</span></a>`).join('')}</div>
<div class="home-lower"><div><div class="section-head"><h2>下一个小期待</h2><a href="#dates">全部纪念日 ${icon('arrow')}</a></div>${milestone(next.title,next.date,next.sub)}</div><div>${latest?`<div class="section-head"><h2>最新点滴</h2><a href="#diary">全部日常 ${icon('arrow')}</a></div><button class="latest-card" data-memory="${escapeHTML(latest.id)}"><span class="tag">${dayTag(latest.date)}</span><h3>${escapeHTML(latest.title)}</h3><p>${escapeHTML((latest.body||'').slice(0,60))}${(latest.body||'').length>60?'……':''}</p><span class="latest-meta">${escapeHTML(latest.date)}${placeTag(latest.place)}</span></button>`:`<div class="section-head"><h2>小狗的悄悄话</h2></div><div class="mini-card">${dog}<div><span class="tag">今日份喜欢</span><p>世界很大，<br>我的小世界刚好有你。</p></div></div>`}</div></div>
<section id="footprints" class="home-footprints" aria-label="我们的足迹">${footprints()}</section><div class="section-head"><h2>镜头里的我们</h2><a href="#album">翻开回忆相册 ${icon('arrow')}</a></div><div class="album-grid home-photos">${photos.slice(0,2).map(photoCard).join('')}</div><section class="quote-banner"><div class="banner-art" aria-hidden="true"><div class="sun"></div>${tree}</div><div class="quote-copy"><div class="eyebrow">FLIPPED · 怦然心动</div><blockquote class="flipped-quote">总有一天，你会遇到<br>一个彩虹般绚丽的人。</blockquote><h2>而我遇见了你，<br>想把故事写得长一点。</h2><p>从今天开始，收藏我们的每一个小瞬间。</p><a class="button" href="#diary">${icon('book')}去记录今天</a></div></section><section id="home-guestbook" class="home-guestbook" aria-label="留言板">${guestbook()}</section>`;}
function empty(i,title,sub,action=""){return `<div class="empty"><div class="empty-icon">${icon(i)}</div><h3>${title}</h3><p>${sub}</p>${action}</div>`;}
function entryCard(e,type){const wish=type==='wishes',id=escapeHTML(e.id);return `<article class="entry ${wish?(e.done?'done':'locked'):''}">${wish?`<span class="lock-badge">${icon(e.done?'unlock':'lock')}</span>`:''}<span class="tag">${wish?(e.done?'已解锁':'待解锁'):dayTag(e.date)}</span><h3>${escapeHTML(e.title)}</h3><div class="entry-meta"><time>${wish&&e.done?`${escapeHTML(e.doneDate||e.date)} 完成`:escapeHTML(e.date)}</time>${placeTag(e.place)}</div>${e.body?`<p>${escapeHTML(e.body)}</p>`:''}${hasImage(e)?`<img class="entry-img" src="${imgSrc(e)}" alt="记录配图" loading="lazy">`:''}${adminActions(e,type)}</article>`;}
function diary(){return heading('OUR EVERYDAY','日常碎碎念','大事小事，想和你分享的都是好事。',addButton('diary','写一篇日常'))+`<div class="entries">${data.diary.length?[...data.diary].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>entryCard(e,'diary')).join(''):empty('book','我们的第一篇日常，等你来写','今天是故事的开始。<br>记下一句话，也是一份小小的喜欢。',addButton('diary','写下第一篇'))}</div>`;}
function wishes(){const list=data.wishes.filter(e=>filter==='all'||(filter==='done'?e.done:!e.done)),done=data.wishes.filter(e=>e.done).length,pct=data.wishes.length?Math.round(done/data.wishes.length*100):0;return heading('OUR LITTLE WISHLIST','一起完成的事','把「有机会」变成「我们一起去」。',addButton('wishes','添加心愿'))+`<div class="progress-card"><div class="progress-text"><b>${done}<small> / ${data.wishes.length}</small></b><span>${data.wishes.length?`已解锁 ${pct}% 的小心愿`:'还没有心愿，先许一个吧'}</span></div><div class="progress big"><i style="width:${pct}%"></i></div></div><div class="filters">${[['all','全部心愿'],['pending','待解锁'],['done','已解锁']].map(([v,t])=>`<button class="filter ${filter===v?'selected':''}" data-filter="${v}">${t}</button>`).join('')}</div><div class="entries">${list.length?list.map(e=>entryCard(e,'wishes')).join(''):empty('star',filter==='all'?'好想和你，一起做好多事':'这里还空空的',filter==='all'?'一起看海、一起散步、一起吃喜欢的东西……<br>把第一个小心愿写在这里吧。':'换个筛选看看，或者再添一个小心愿。',addButton('wishes','添加心愿'))}</div>`;}
function dates(){return heading('DAYS TO REMEMBER','我们的纪念日','有你的日子，都值得被认真记住。',addButton('dates','添加纪念日'))+`<div class="date-list">${milestone('故事开始的那一天',start,'小年 ♡ 小年对象')}${automaticDates.map(e=>milestone(e.title,e.date,e.sub)).join('')}${data.dates.map(e=>`<div class="date-item">${milestone(e.title,e.date,e.body||'属于我们的小纪念')}${adminActions(e,'dates')}</div>`).join('')}</div>`;}
function album(){const daily=data.diary.filter(hasImage).sort((a,b)=>b.date.localeCompare(a.date)),groups=[...albums.map(g=>({...g,count:g.photos.length,cover:photos[g.photos[0]].src,cover2:photos[g.photos[1]]?.src})),...(daily.length?[{id:'daily',title:'日常里的照片',note:'来自日常碎碎念',count:daily.length,cover:imgSrc(daily[0]),cover2:daily[1]&&imgSrc(daily[1])}]:[])];
return `<section class="album-full">${heading('OUR MEMORY BOX','回忆收藏夹','照片会替我们记住，那些舍不得忘记的瞬间。')}<div class="collections">${groups.map(g=>`<button class="collection" data-scroll="group-${g.id}"><span class="stack">${g.cover2?`<img src="${g.cover2}" alt="" loading="lazy">`:''}<img src="${g.cover}" alt="" loading="lazy"></span><b>${g.title}</b><small>${g.count} 张 · ${g.note}</small></button>`).join('')}</div>${albums.map(g=>`<section class="album-group" id="group-${g.id}"><div class="group-head"><h3>${g.title}</h3><span>${g.photos.length} 张</span></div><div class="album-grid">${g.photos.map(i=>photoCard(photos[i],i)).join('')}</div></section>`).join('')}${daily.length?`<section class="album-group" id="group-daily"><div class="group-head"><h3>日常里的照片</h3><span>${daily.length} 张</span></div><div class="album-grid">${daily.map(e=>`<button class="polaroid" data-memory="${escapeHTML(e.id)}"><img src="${imgSrc(e)}" alt="${escapeHTML(e.title)}" loading="lazy"><p>${escapeHTML(e.title)}</p><small>${dayTag(e.date)} · ${escapeHTML(e.date)}</small></button>`).join('')}</div></section>`:''}</section>`;}
function footprints(){const list=footprintList(),places=new Set(list.map(e=>e.place));return heading('STEPS OF US','我们的足迹','一起走过的地方，都会在地图上亮起来。',addButton('places','标记一个地方'))+`<div class="stats"><div class="stat"><b>${places.size}</b><span>去过的地方</span></div><div class="stat"><b id="lit-count">–</b><span>点亮的省份</span></div><div class="stat"><b>${list.length}</b><span>留下的足迹</span></div></div><div class="map-card"><div class="map-toolbar"><span class="map-hint">${icon('pin')}粉色是去过的省份 · 滚轮或双指可以缩放</span><div class="map-controls"><button class="map-zoom" data-map-zoom="out" aria-label="缩小地图">−</button><output id="map-zoom-level" aria-live="polite">100%</output><button class="map-zoom" data-map-zoom="in" aria-label="放大地图">＋</button><button class="soft-button" data-map-zoom="reset">复位</button><button class="soft-button" data-map-toggle>${icon('expand')}<span>展开地图</span></button></div></div><div id="china-map" class="china-map"><p class="muted map-loading">地图加载中…</p></div><div class="map-sizing"><span>拖动右下角，调整地图高度</span><button class="map-resize-handle" aria-label="拉伸地图高度" title="上下拖动调整高度；也可使用上下方向键">↕</button></div></div>`+(list.length?`<ol class="timeline">${list.map(e=>`<li><span class="dot">${icon('pin')}</span><div class="timeline-card"><div class="timeline-top"><b>${escapeHTML(e.place)}</b><span class="tag">${e.kind==='wish'?'解锁心愿':e.kind==='place'?'足迹':dayTag(e.date)}</span></div><h3>${escapeHTML(e.kind==='place'?(e.body||'一起来过这里 ♡'):e.title)}</h3><time>${escapeHTML(e.date)}</time>${e.kind==='place'?adminActions(e,'places'):''}</div></li>`).join('')}</ol>`:`<div class="entries">${empty('pin','还没有足迹哦',isAdmin()?'点「标记一个地方」，或者写日常时填上「地点」，<br>去过的地方就会在地图上亮起来。':'等我们一起出发，<br>去过的地方会在地图上亮起来。')}</div>`);}
// ===== 足迹地图：ECharts + 阿里云 DataV 的中国地图边界 =====
// 地点里出现这些城市名就精确标点；只写了省份就标在省份中心
const CITIES={北京:[116.40,39.90],上海:[121.47,31.23],天津:[117.20,39.08],重庆:[106.55,29.56],长沙:[112.94,28.23],广州:[113.26,23.13],深圳:[114.06,22.54],杭州:[120.16,30.27],南京:[118.80,32.06],苏州:[120.58,31.30],武汉:[114.30,30.59],成都:[104.07,30.57],西安:[108.94,34.34],厦门:[118.09,24.48],青岛:[120.38,36.07],大连:[121.61,38.91],哈尔滨:[126.63,45.75],长春:[125.32,43.82],沈阳:[123.43,41.80],济南:[117.00,36.65],郑州:[113.62,34.75],合肥:[117.23,31.82],南昌:[115.86,28.68],福州:[119.30,26.08],昆明:[102.83,24.88],大理:[100.27,25.61],丽江:[100.23,26.87],贵阳:[106.63,26.65],南宁:[108.37,22.82],桂林:[110.29,25.27],海口:[110.32,20.03],三亚:[109.51,18.25],拉萨:[91.13,29.65],西宁:[101.78,36.62],兰州:[103.83,36.06],银川:[106.23,38.49],乌鲁木齐:[87.62,43.83],呼和浩特:[111.75,40.84],太原:[112.55,37.87],石家庄:[114.51,38.04],香港:[114.17,22.32],澳门:[113.54,22.19],台北:[121.56,25.04],无锡:[120.30,31.57],宁波:[121.55,29.87],温州:[120.70,28.00],绍兴:[120.58,30.03],扬州:[119.42,32.39],珠海:[113.58,22.27],佛山:[113.12,23.02],东莞:[113.75,23.02],株洲:[113.13,27.83],湘潭:[112.94,27.83],岳阳:[113.13,29.36],衡阳:[112.57,26.89],张家界:[110.48,29.12],凤凰:[109.60,27.95],洛阳:[112.45,34.62],开封:[114.31,34.80],黄山:[118.34,29.71],九江:[116.00,29.71],泉州:[118.68,24.87],烟台:[121.45,37.46],威海:[122.12,37.51],秦皇岛:[119.60,39.94],承德:[117.96,40.95],宜昌:[111.29,30.69],恩施:[109.49,30.27],乐山:[103.77,29.55],九寨沟:[103.92,33.26],西双版纳:[100.80,22.01],敦煌:[94.66,40.14],喀什:[75.99,39.47],伊犁:[81.32,43.92]};
const HEART_PATH='path://M12 21S1.5 14.6.3 8.4A6 6 0 0 1 12 4.3a6 6 0 0 1 11.7 4.1C22.5 14.6 12 21 12 21z';
let chart=null,geoReady=null,mapHeight=null;
function loadScript(src){return new Promise((res,rej)=>{const s=document.createElement('script');s.src=src;s.onload=res;s.onerror=rej;document.head.append(s);});}
// 地图数据来自阿里云 DataV，ECharts 5.5.0 与其许可证随站点托管，避免外部资源加载失败。
function ensureMap(){if(!geoReady)geoReady=Promise.all([fetch('assets/china-map.json').then(r=>{if(!r.ok)throw new Error();return r.json();}),window.echarts?null:loadScript('assets/echarts-5.5.0.min.js')]).then(([geo])=>{echarts.registerMap('china',geo);return geo;}).catch(e=>{geoReady=null;throw e;});return geoReady;}
function inRing(pt,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const [xi,yi]=ring[i],[xj,yj]=ring[j];if((yi>pt[1])!==(yj>pt[1])&&pt[0]<(xj-xi)*(pt[1]-yi)/(yj-yi)+xi)inside=!inside;}return inside;}
function provinceOf(pt,geo){return geo.features.find(f=>{const g=f.geometry;if(!g)return false;const polys=g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[];return polys.some(p=>inRing(pt,p[0]));});}
const shortName=n=>n.replace(/(壮族|回族|维吾尔)?自治区$|特别行政区$|省$|市$/,'');
function locate(text,geo){const city=Object.keys(CITIES).filter(c=>text.includes(c)).sort((a,b)=>b.length-a.length)[0];if(city){const f=provinceOf(CITIES[city],geo);return {label:city,coord:CITIES[city],province:f?.properties.name};}const f=geo.features.find(f=>f.properties.name&&text.includes(shortName(f.properties.name)));return f?{label:shortName(f.properties.name),coord:f.properties.center||f.properties.centroid,province:f.properties.name}:null;}
async function drawMap(){const el=$('#china-map');if(!el)return;try{const geo=await ensureMap();if(!document.body.contains(el))return;const groups=new Map(),lit=new Set();for(const e of footprintList()){const loc=locate(e.place,geo);if(!loc)continue;if(loc.province)lit.add(loc.province);const g=groups.get(loc.label)||{...loc,items:[]};g.items.push(e);groups.set(loc.label,g);}const homes=people.filter(p=>p.lat!=null).map(p=>({name:p.name,value:[p.lon,p.lat],tip:`<b>${escapeHTML(p.name)}</b> 在 ${escapeHTML(p.city)}`,label:`${p.name}`}));const counter=$('#lit-count');if(counter)counter.textContent=lit.size;chart?.dispose();el.innerHTML='';chart=echarts.init(el);chart.setOption({tooltip:{trigger:'item',backgroundColor:'rgba(255,255,255,.92)',borderColor:'#f6cbd4',textStyle:{color:'#4a3a2e',fontSize:13},formatter:p=>p.data?.tip||(lit.has(p.name)?`${p.name} · 来过啦 ♡`:p.name)},geo:{map:'china',roam:true,layoutCenter:['50%','50%'],layoutSize:'96%',scaleLimit:{min:1,max:10},label:{show:el.clientWidth>=520,color:'#96725f',fontSize:10,formatter:p=>shortName(p.name||'')},itemStyle:{areaColor:'#fff8ed',borderColor:'#cda994',borderWidth:1},emphasis:{itemStyle:{areaColor:'#ffe3ea'},label:{show:true,color:'#8a5a4a'}},select:{disabled:true},regions:[...lit].map(name=>({name,itemStyle:{areaColor:'#ffc4d2',borderColor:'#f19fb3'}}))},series:[{type:'lines',coordinateSystem:'geo',zlevel:1,effect:{show:true,period:5,symbol:HEART_PATH,symbolSize:11,color:'#f0607e',trailLength:0},lineStyle:{color:'#f48aa4',width:1.6,type:'dashed',curveness:.3,opacity:.85},data:homes.length===2?[{coords:[homes[0].value,homes[1].value]}]:[]},{type:'effectScatter',coordinateSystem:'geo',zlevel:2,rippleEffect:{brushType:'stroke',scale:4},symbolSize:d=>Math.min(16,7+d[2]*2),itemStyle:{color:'#f0607e',shadowBlur:10,shadowColor:'rgba(240,96,126,.6)'},label:{show:true,formatter:'{b}',position:'right',color:'#7a4a3a',fontSize:11},data:[...groups.values()].map(g=>({name:g.label,value:[...g.coord,g.items.length],tip:`<b>${escapeHTML(g.label)}</b> · ${g.items.length} 段足迹<br>${g.items.slice(0,5).map(e=>escapeHTML(e.kind==='place'?(e.body||e.place):e.title)).join('<br>')}`}))},{type:'scatter',coordinateSystem:'geo',zlevel:3,symbol:HEART_PATH,symbolSize:[20,18],itemStyle:{color:'#ff8fab',borderColor:'#fff',borderWidth:1.5,shadowBlur:8,shadowColor:'rgba(240,96,126,.5)'},label:{show:true,formatter:p=>p.data.label,position:'top',color:'#c4566b',fontSize:12,fontWeight:'bold'},data:homes}]});chart.on('georoam',updateMapZoom);updateMapZoom();}catch{el.innerHTML='<p class="muted map-loading">地图加载失败，请检查网络后刷新。</p>';}}
function toggleMap(btn){const card=btn.closest('.map-card'),open=!card.classList.contains('expanded');card.classList.toggle('expanded',open);document.body.classList.toggle('map-open',open);btn.innerHTML=open?`${icon('collapse')}<span>收起地图</span>`:`${icon('expand')}<span>展开地图</span>`;requestAnimationFrame(resizeMap);}
function resizeMap(){if(!chart)return;chart.resize();chart.setOption({geo:{label:{show:chart.getWidth()>=520}}});}
function updateMapZoom(){const level=$('#map-zoom-level');if(level&&chart)level.textContent=Math.round((chart.getOption().geo[0].zoom||1)*100)+'%';}
function zoomMap(action){if(!chart)return;if(action==='reset'){chart.setOption({geo:{center:null,zoom:1}});}else{const current=chart.getOption().geo[0].zoom||1,target=Math.min(10,Math.max(1,current*(action==='in'?1.25:.8)));chart.dispatchAction({type:'geoRoam',componentType:'geo',geoIndex:0,zoom:target/current,originX:chart.getWidth()/2,originY:chart.getHeight()/2});}updateMapZoom();}
function initMapControls(){const el=$('#china-map'),handle=$('.map-resize-handle');if(!el||!handle)return;if(mapHeight!==null)el.style.setProperty('--map-height',mapHeight+'px');let drag=null,frame=null;const setHeight=h=>{mapHeight=Math.min(1400,Math.max(320,Math.round(h)));el.style.setProperty('--map-height',mapHeight+'px');handle.setAttribute('aria-label','拉伸地图高度，当前 '+mapHeight+' 像素');cancelAnimationFrame(frame);frame=requestAnimationFrame(resizeMap);};handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();drag={id:e.pointerId,y:e.clientY,height:el.clientHeight};handle.setPointerCapture(e.pointerId);};handle.onpointermove=e=>{if(drag&&drag.id===e.pointerId)setHeight(drag.height+e.clientY-drag.y);};const finish=()=>{drag=null;};handle.onpointerup=finish;handle.onpointercancel=finish;handle.onlostpointercapture=finish;handle.onkeydown=e=>{if(['ArrowUp','ArrowDown','Home'].includes(e.key)){e.preventDefault();if(e.key==='Home'){mapHeight=null;el.style.removeProperty('--map-height');handle.setAttribute('aria-label','拉伸地图高度');resizeMap();}else setHeight(el.clientHeight+(e.key==='ArrowDown'?60:-60));}};}
addEventListener('resize',resizeMap);
addEventListener('keydown',e=>{if(e.key==='Escape'){const b=$('.map-card.expanded [data-map-toggle]');if(b)toggleMap(b);}});
function localRecords(){try{const d=cleanData(JSON.parse(localStorage.getItem(key)));return d&&d.diary.length+d.wishes.length+d.dates.length?d:null;}catch{return null;}}
function admin(){if(isAdmin())return heading('ADMIN','后台管理','你已登录管理员，可以在各个页面添加、编辑和删除内容。')+`<section class="admin-card"><h3>${icon('unlock')} 已登录管理员</h3><p class="muted">保存后约 1 分钟，所有访客都能看到更新。在公共电脑上用完记得退出。</p><div class="admin-actions"><button class="button secondary" id="logout">${icon('lock')}退出登录</button></div></section><section class="admin-card"><h3>数据备份</h3><p class="muted">导出网站上的全部记录。导入会替换网站上现有的日常、心愿和纪念日。</p><div class="admin-actions"><button class="button" id="backup">${icon('download')}导出记录</button><button class="button secondary" id="restore">${icon('upload')}导入备份到网站</button>${localRecords()?`<button class="button secondary" id="migrate">${icon('upload')}把本机旧记录上传到网站</button>`:''}</div></section>`;
return heading('ADMIN','管理员登录','登录后才能添加和修改内容，游客只能浏览和留言。')+`<section class="admin-card"><form id="login-form" class="admin-form"><label>管理员密码<input name="pw" type="password" autocomplete="current-password" required></label><label class="check"><input type="checkbox" name="remember" checked>在这台设备上保持登录</label><p class="form-error" role="alert"></p><div class="admin-actions"><button class="button" type="submit">${icon('unlock')}登录</button></div></form></section><details class="admin-card"><summary>首次设置 / 重置管理员密码</summary><p class="muted">需要一个只授权 love-house 仓库、Contents 为读写权限的 GitHub 令牌。令牌会用你设置的密码加密后保存在仓库里，之后在任何设备上只需输入密码就能登录。</p><form id="setup-form" class="admin-form"><label>GitHub 令牌<input name="token" type="password" autocomplete="off" required placeholder="github_pat_..."></label><label>设置管理员密码（至少 8 位）<input name="pw" type="password" autocomplete="new-password" minlength="8" required></label><label>再输入一次<input name="pw2" type="password" autocomplete="new-password" minlength="8" required></label><p class="form-error" role="alert"></p><div class="admin-actions"><button class="button" type="submit">保存设置并登录</button></div></form></details>`;}
function render(){const p=page();if(chart){chart.dispose();chart=null;}document.body.classList.remove('map-open');document.body.classList.toggle('is-admin',isAdmin());const badge=$('#admin-badge');if(badge)badge.hidden=!isAdmin();$('#content').innerHTML=({home,diary,dates,wishes,album,admin})[p]();document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===p);if(a.dataset.page===p)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(p==='home')loadWeather();if($('#china-map')){initMapControls();drawMap();}if(location.hash==='#footprints')requestAnimationFrame(scrollToFootprints);}
// ===== 双方天气与距离 =====
function wx(c,day){return c===0?[day?'☀️':'🌙','晴']:c===1?[day?'🌤️':'🌙','晴间多云']:c===2?['⛅','多云']:c===3?['☁️','阴']:c<50?['🌫️','雾']:c<60?['🌦️','毛毛雨']:c<70?['🌧️','雨']:c<80?['🌨️','雪']:c<83?['🌦️','阵雨']:c<90?['🌨️','阵雪']:['⛈️','雷阵雨'];}
function km(a,b){const r=x=>x*Math.PI/180,d=Math.sin(r(b.lat-a.lat)/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(r(b.lon-a.lon)/2)**2;return 6371*2*Math.asin(Math.sqrt(d));}
async function loadWeather(){const box=$('#weather');if(!box||!people.every(p=>p.lat!=null&&p.lon!=null))return;try{if(!weatherCache||Date.now()-weatherCache.t>600000){const res=await Promise.all(people.map(p=>fetch(`https://api.open-meteo.com/v1/forecast?latitude=${p.lat}&longitude=${p.lon}&current=temperature_2m,relative_humidity_2m,weather_code,wind_speed_10m,is_day&daily=temperature_2m_max,temperature_2m_min&timezone=Asia%2FShanghai&forecast_days=1`).then(r=>{if(!r.ok)throw new Error();return r.json();})));weatherCache={t:Date.now(),res};}const card=(p,w)=>{const [e,text]=wx(w.current.weather_code,w.current.is_day);return `<div class="weather-card"><div class="w-top"><span class="w-name">${escapeHTML(p.name)}</span><span class="w-city">${icon('pin')}${escapeHTML(p.city)}</span></div><div class="w-main"><span class="w-emoji">${e}</span><b>${Math.round(w.current.temperature_2m)}°</b></div><div class="w-sub">${text} · ${Math.round(w.daily.temperature_2m_min[0])}° / ${Math.round(w.daily.temperature_2m_max[0])}°</div><div class="w-sub">湿度 ${w.current.relative_humidity_2m}% · 风 ${Math.round(w.current.wind_speed_10m)} km/h</div></div>`;},d=km(people[0],people[1]),el=$('#weather');if(!el)return;el.innerHTML=card(people[0],weatherCache.res[0])+`<div class="w-distance">${d<1?`<b>同城</b><span>就在身边 ♡</span>`:`<span>相距</span><b>${d.toFixed(1)}</b><span>km</span>`}</div>`+card(people[1],weatherCache.res[1]);el.hidden=false;}catch{box.hidden=true;}}
// ===== 照片与随机回忆 =====
function showMemory(m){$('#lb-content').innerHTML=`${m.image?`<img src="${m.image}" alt="${escapeHTML(m.title)}">`:''}<div class="lb-text">${m.tag?`<span class="tag">${m.tag}</span>`:''}<h3>${escapeHTML(m.title)}</h3>${m.meta?`<div class="entry-meta">${m.meta}</div>`:''}${m.body?`<p>${escapeHTML(m.body)}</p>`:''}${m.random?`<button class="soft-button" data-random>${icon('shuffle')}再翻一段</button>`:''}</div>`;const lb=$('#lightbox');if(!lb.open)lb.showModal();}
function entryMemory(e,random=false){return {image:hasImage(e)?imgSrc(e):'',title:e.title,tag:e.kind==='wish'||data.wishes.includes(e)?'解锁的心愿':dayTag(e.date),meta:`<time>${escapeHTML(e.date)}</time>${placeTag(e.place)}`,body:e.body,random};}
function showRandom(){const pool=[...photos.map(p=>({image:p.src,title:p.title,tag:'相册',meta:`<time>${p.note}</time>`})),...data.diary.map(e=>entryMemory(e)),...data.wishes.filter(e=>e.done).map(e=>entryMemory(e))];const pick=pool[Math.floor(Math.random()*pool.length)];showMemory({...pick,random:true});}
function openEditor(type,id){if(!isAdmin())return;editing={type,id};const form=$('#entry-form');form.reset();const e=data[type].find(e=>e.id===id);$('#dialog-title').textContent=(e?'编辑':'添加')+({diary:'日常',wishes:'心愿',dates:'纪念日',places:'足迹'})[type];form.elements.title.placeholder=type==='places'?'地点，比如：长沙 · 橘子洲':'给这一刻取个名字';form.elements.title.value=e?.title||'';form.elements.date.value=e?.date||today();form.elements.body.value=e?.body||'';form.elements.place.value=e?.place||'';$('#image-label').hidden=type==='dates';$('#place-label').hidden=type==='dates'||type==='places';$('#form-error').textContent='';$('#editor').showModal();}
// 浏览器存储只有约 5 MB，所以配图先缩到最长边 1600px 再存，原图大小不影响保存
function readImage(file,max=1600,quality=.82){return new Promise((resolve,reject)=>{if(!file)return resolve(null);if(!['image/png','image/jpeg','image/webp'].includes(file.type))return reject(new Error('请选择 PNG、JPG 或 WebP 图片。'));if(file.size>20*1024*1024)return reject(new Error('配图请小于 20 MB。'));const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{const scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),c=document.createElement('canvas');c.width=Math.round(img.naturalWidth*scale);c.height=Math.round(img.naturalHeight*scale);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL('image/jpeg',quality));};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('图片读取失败，请重试。'));};img.src=url;});}
$('#entry-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]'),label=button.innerHTML;button.disabled=true;button.textContent='保存中…';try{const title=form.elements.title.value.trim();if(!title)throw new Error('请填写标题。');const {type,id}=editing,dataUrl=await readImage(form.elements.image.files[0]),image=dataUrl?await uploadImage(dataUrl):null,fields={title,date:form.elements.date.value,body:form.elements.body.value.trim(),place:type==='dates'||type==='places'?'':form.elements.place.value.trim()};let replaced=null;await commitData(d=>{const old=d[type].find(e=>e.id===id),e={id:old?.id||crypto.randomUUID(),...fields,image:image??old?.image??'',done:old?.done||false,...(old?.doneDate?{doneDate:old.doneDate}:{})};if(image&&/^uploads\//.test(old?.image||''))replaced=old.image;d[type]=old?d[type].map(x=>x.id===id?e:x):[...d[type],e];return d;},`${id?'编辑':'添加'}：${title}`);if(replaced)removeFile(replaced,'删除旧图片');$('#editor').close();render();notify('保存好啦 ♡ 约 1 分钟后所有人都能看到');}catch(e){$('#form-error').textContent=e.message;}finally{button.disabled=false;button.innerHTML=label;}});
document.addEventListener('click',e=>{if(e.target.closest('a[href="#footprints"]')&&location.hash==='#footprints'){e.preventDefault();scrollToFootprints();return;}const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.dataset.add)openEditor(b.dataset.add);if(b.dataset.edit)openEditor(b.dataset.type,b.dataset.edit);if(b.dataset.delete&&isAdmin()){pendingDelete={type:b.dataset.type,id:b.dataset.delete};document.querySelector('#delete-dialog').showModal();}if(b.dataset.toggle&&isAdmin()){b.disabled=true;let nowDone=false;commitData(d=>{const x=d.wishes.find(x=>x.id===b.dataset.toggle);if(x){x.done=!x.done;nowDone=x.done;if(x.done)x.doneDate=today();else delete x.doneDate;}return d;},'更新心愿状态').then(()=>{render();notify(nowDone?'又解锁了一个心愿 ♡':'已重新上锁');}).catch(err=>{notify(err.message);b.disabled=false;});}if(b.id==='backup')exportBackup();if(b.id==='restore')$('#restore-file').click();if(b.id==='migrate')migrateLocal();if(b.id==='logout'){logout();notify('已退出登录');}if(b.dataset.filter){filter=b.dataset.filter;render();}if(b.dataset.random!==undefined)showRandom();if(b.dataset.scroll)document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});if(b.dataset.memory){const m=data.diary.find(x=>x.id===b.dataset.memory);if(m)showMemory(entryMemory(m));}if(b.dataset.photo!==undefined){const p=photos[Number(b.dataset.photo)];showMemory({image:p.src,title:p.title,meta:`<time>${p.note}</time>`});}if(b.dataset.gbImage){showMemory({image:gbImageUrl(b.dataset.gbImage),title:b.dataset.gbTitle||'留言图片'});}if(b.dataset.gbDelete)deleteMessage(b.dataset.gbDelete,b);if(b.dataset.mapToggle!==undefined)toggleMap(b);if(b.dataset.mapZoom)zoomMap(b.dataset.mapZoom);});
// 管理员登录与首次设置
document.addEventListener('submit',async event=>{const form=event.target;if(!['login-form','setup-form','guest-form'].includes(form.id))return;event.preventDefault();const err=form.querySelector('.form-error'),button=form.querySelector('[type=submit]'),label=button.innerHTML;err.textContent='';button.disabled=true;try{if(form.id==='login-form'){button.textContent='登录中…';await login(form.elements.pw.value,form.elements.remember.checked);notify('欢迎回来 ♡ 已进入管理员模式');await loadData();}else if(form.id==='setup-form'){if(form.elements.pw.value!==form.elements.pw2.value)throw new Error('两次输入的密码不一样。');button.textContent='保存中…';await setupAdmin(form.elements.token.value.trim(),form.elements.pw.value);notify('管理员设置好啦 ♡ 以后输入密码就能登录');await loadData();}else await postMessage(form);}catch(e){err.textContent=e.message||'出错了，请稍后再试。';}finally{button.disabled=false;button.innerHTML=label;}});
function exportBackup(){const blob=new Blob([JSON.stringify({version:2,...data},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`小年的爱情小屋-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('备份已导出，请妥善保存。');};
function validRecords(d){const str=v=>v===undefined||typeof v==='string';return ['diary','wishes','dates','places'].every(type=>(type==='places'&&d?.places===undefined)||Array.isArray(d?.[type])&&d[type].every(e=>e&&typeof e.id==='string'&&/^[\w-]+$/.test(e.id)&&typeof e.title==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(e.date)&&Number.isFinite(epoch(e.date))&&str(e.body)&&str(e.image)&&str(e.place)&&(e.doneDate===undefined||/^\d{4}-\d{2}-\d{2}$/.test(e.doneDate))&&(e.done===undefined||typeof e.done==='boolean')));}
// 把备份或本机旧记录搬到网站上：内嵌的图片先上传成文件，再写入 data.json
async function importToCloud(d,merge){notify('正在上传，请稍等…');const out={diary:[],wishes:[],dates:[],places:[]};const types=['diary','wishes','dates','places'];for(const type of types)for(const e of d[type]||[])out[type].push({...e,image:/^data:image\//.test(e.image||'')?await uploadImage(e.image):(hasImage(e)?e.image:'')});await commitData(cur=>merge?Object.fromEntries(types.map(t=>[t,[...cur[t],...out[t].filter(x=>!cur[t].some(y=>y.id===x.id))]])):out,merge?'上传本机旧记录':'导入备份');render();notify('小回忆都搬到网站上啦 ♡');}
async function migrateLocal(){const d=localRecords();if(!d||!confirm(`把这台设备上的 ${d.diary.length} 篇日常、${d.wishes.length} 个心愿、${d.dates.length} 个纪念日上传到网站？`))return;try{await importToCloud(d,true);try{localStorage.removeItem(key);}catch{}render();}catch(e){notify(e.message);}}
$('#restore-file').onchange=async event=>{const input=event.target,file=input.files[0];if(!file)return;try{if(!isAdmin())throw new Error('只有管理员可以导入。');if(file.size>15*1024*1024)throw new Error('备份文件过大。');const imported=JSON.parse(await file.text());if(!validRecords(imported))throw new Error('备份内容格式不正确。');if(!confirm('导入会替换网站上现有的日常、心愿和自定义纪念日，是否继续？'))return;await importToCloud(imported,false);}catch(e){notify(e.message||'导入失败，请选择正确的备份文件。');}finally{input.value='';}};
$('#confirm-delete').onclick=async()=>{if(!pendingDelete||!isAdmin())return;const {type,id}=pendingDelete,btn=$('#confirm-delete');btn.disabled=true;try{let img='';await commitData(d=>{img=d[type].find(e=>e.id===id)?.image||'';d[type]=d[type].filter(e=>e.id!==id);return d;},'删除一条记录');if(/^uploads\//.test(img))removeFile(img,'删除图片');render();$('#delete-dialog').close();notify('记录已删除。');}catch(e){notify(e.message);}finally{btn.disabled=false;pendingDelete=null;}};
// ===== 留言板：任何人都能留言（文字 + 图片），数据在 Supabase；删除需要管理员密码 =====
// 在 Supabase 建好项目后，把 Project URL 和 anon public key 填到这里
const GUESTBOOK={url:'',anonKey:''};
let messages=null,guestPw=null,messagesLoading=false;
const gbReady=()=>!!(GUESTBOOK.url&&GUESTBOOK.anonKey);
function gbHeaders(extra={}){return {apikey:GUESTBOOK.anonKey,Authorization:`Bearer ${GUESTBOOK.anonKey}`,...extra};}
function gbImageUrl(name){return /^[0-9a-f-]{36}\.jpg$/.test(name)?`${GUESTBOOK.url}/storage/v1/object/public/guestbook/${name}`:'';}
function deviceName(){const u=navigator.userAgent;return /iPhone|iPad|iPod/.test(u)?'iPhone':/Android/.test(u)?'Android':/Mac/.test(u)?'Mac':/Windows/.test(u)?'Windows':'其他设备';}
function timeAgo(iso){const s=(Date.now()-Date.parse(iso))/1000;if(s<60)return '刚刚';if(s<3600)return `${Math.floor(s/60)} 分钟前`;if(s<86400)return `${Math.floor(s/3600)} 小时前`;if(s<86400*7)return `${Math.floor(s/86400)} 天前`;return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric'}).format(new Date(iso));}
function avatarColor(name){let h=0;for(const c of name)h=(h*31+c.codePointAt(0))%360;return `hsl(${h} 70% 82%)`;}
async function loadMessages(){if(!gbReady()||messagesLoading)return;messagesLoading=true;try{const r=await fetch(`${GUESTBOOK.url}/rest/v1/guestbook?select=*&order=created_at.desc&limit=200`,{headers:gbHeaders(),cache:'no-store'});if(!r.ok)throw new Error();messages=await r.json();}catch{messages=messages||[];notify('留言加载失败，请稍后刷新。');}messagesLoading=false;const list=$('#home-guestbook .messages');if(list)list.innerHTML=messageList();}
function messageCard(m){const img=gbImageUrl(m.image||''),name=escapeHTML(m.name);return `<article class="message"><div class="msg-head"><span class="msg-avatar" style="background:${avatarColor(m.name)}">${escapeHTML([...m.name][0]||'♡')}</span><div><b>${name}</b><span class="msg-meta">${timeAgo(m.created_at)}${m.device?` · ${escapeHTML(m.device)}`:''}</span></div>${isAdmin()?`<button class="msg-delete" data-gb-delete="${escapeHTML(m.id)}" aria-label="删除这条留言">${icon('trash')}</button>`:''}</div>${m.content?`<p>${escapeHTML(m.content)}</p>`:''}${img?`<button class="msg-image" data-gb-image="${escapeHTML(m.image)}" data-gb-title="${name} 的留言"><img src="${img}" alt="${name} 留言的图片" loading="lazy"></button>`:''}</article>`;}
function messageList(){return messages===null?'<p class="muted loading">留言加载中…</p>':messages.length?messages.map(messageCard).join(''):empty('heart','还没有人留言','来做第一个留下祝福的人吧 ♡');}
function guestbook(){if(gbReady()&&messages===null)loadMessages();let saved='';try{saved=localStorage.getItem('xiaonian-guest-name')||'';}catch{}return heading('KIND MESSAGES','留言板','路过的朋友，留下一句祝福吧，也可以配一张图 ♡')+(!gbReady()?`<div class="entries">${empty('heart','留言板还在搭建中','很快就可以在这里留下祝福啦。')}</div>`:`<form id="guest-form" class="guest-form"><div class="guest-row"><label>你的名字<input name="name" maxlength="20" required value="${escapeHTML(saved)}" placeholder="怎么称呼你"></label></div><label>想说的话<textarea name="content" maxlength="500" rows="3" placeholder="写下祝福、悄悄话，或者一句你好～"></textarea></label><input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><div class="guest-actions"><label class="file-pill">${icon('image')}<span>添加图片</span><input name="image" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><span class="file-name"></span><button class="button" type="submit">${icon('heart')}留下祝福</button></div><p class="form-error" role="alert"></p></form><div class="messages">${messageList()}</div>`);}
async function postMessage(form){if(form.elements.website.value)return;const name=form.elements.name.value.trim(),content=form.elements.content.value.trim(),file=form.elements.image.files[0];if(!name)throw new Error('请写上你的名字。');if(!content&&!file)throw new Error('写点什么，或者放一张图吧。');form.querySelector('[type=submit]').textContent='发送中…';let image=null;if(file){const dataUrl=await readImage(file,1200,.8),blob=await (await fetch(dataUrl)).blob();image=`${crypto.randomUUID()}.jpg`;const up=await fetch(`${GUESTBOOK.url}/storage/v1/object/guestbook/${image}`,{method:'POST',headers:gbHeaders({'Content-Type':'image/jpeg'}),body:blob});if(!up.ok)throw new Error('图片上传失败，请换一张或稍后再试。');}const r=await fetch(`${GUESTBOOK.url}/rest/v1/rpc/post_message`,{method:'POST',headers:gbHeaders({'Content-Type':'application/json'}),body:JSON.stringify({p_name:name,p_content:content,p_image:image,p_device:deviceName()})});if(!r.ok){const j=await r.json().catch(()=>({}));throw new Error(/频繁/.test(j.message||'')?j.message:'留言没发出去，请稍后再试。');}const m=await r.json();try{localStorage.setItem('xiaonian-guest-name',name);}catch{}messages=[m,...(messages||[])];render();notify('谢谢你的祝福 ♡');}
async function deleteMessage(id,btn){if(!isAdmin())return;if(!guestPw){guestPw=prompt('请输入管理员密码以删除留言');if(!guestPw)return;}if(!confirm('确定删除这条留言吗？'))return;btn.disabled=true;try{const r=await fetch(`${GUESTBOOK.url}/rest/v1/rpc/delete_message`,{method:'POST',headers:gbHeaders({'Content-Type':'application/json'}),body:JSON.stringify({p_id:id,p_pw:guestPw})});if(!r.ok){guestPw=null;throw new Error('删除失败：管理员密码不对，或网络有问题。');}messages=messages.filter(m=>m.id!==id);render();notify('留言已删除。');}catch(e){notify(e.message);btn.disabled=false;}}
document.addEventListener('change',e=>{if(e.target.name==='image'&&e.target.closest('#guest-form')){const f=e.target.files[0];e.target.closest('#guest-form').querySelector('.file-name').textContent=f?f.name:'';}});
// 鼠标点击时爆出几颗小爱心（只对鼠标，触屏不触发）
document.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const colors=['#f48aa4','#ffb3c3','#f0607e','#ffd2dc','#ffc98a'];for(let i=0;i<6;i++){const a=Math.PI*2*i/6+Math.random()*.6,d=26+Math.random()*22,h=document.createElement('span');h.className='click-heart';h.style.cssText=`left:${e.clientX}px;top:${e.clientY}px;--dx:${Math.cos(a)*d}px;--dy:${Math.sin(a)*d-10}px;--r:${Math.round(Math.random()*40-20)}deg`;h.innerHTML=`<svg viewBox="0 0 24 22"><path d="M12 21S1.5 14.6.3 8.4A6 6 0 0 1 12 4.3a6 6 0 0 1 11.7 4.1C22.5 14.6 12 21 12 21z" fill="${colors[i%colors.length]}"/></svg>`;document.body.append(h);setTimeout(()=>h.remove(),850);}});
function scrollToFootprints(){document.getElementById('footprints')?.scrollIntoView({block:'start'});}
window.addEventListener('hashchange',()=>{render();if(location.hash!=='#footprints')window.scrollTo(0,0);});
setInterval(()=>{const el=$('#love-day');if(!el)return;const t=together();el.textContent=t.day;for(const k of ['h','m','s']){const c=$('#clock-'+k);if(c&&c.textContent!==t[k])c.textContent=t[k];}},1000);
render();loadData();
